arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"exclude_archived": true, "limit": 1000}' | python3 -c "
import json,sys
d = json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d); sys.exit()
for c in d['channels']:
    if c.get('name') in ('proposals','Proposal','PROPOSALS'):
        print(c['id'], c['name'])
"

